function getTemplateSource(fileName: string): string {
  try {
    const candidates = [
      path.join(process.cwd(), "email-templates", fileName),
      path.join(__dirname, "..", "email-templates", fileName),
      path.join(__dirname, "email-templates", fileName),
    ];
    for (const p of candidates) {
      if (fs.existsSync(p)) {
        return fs.readFileSync(p, "utf-8");
      }
    }
  } catch (err) {
    console.warn("[SendTemplates] Could not load from disk, using bundle fallback:", err);
  }
  return BUNDLED_TEMPLATES[fileName] || "";
}

function renderPlaceholders(html: string, overrides: Record<string, string> = {}): string {
  const merged = { ...DEFAULT_VARIABLES, ...overrides };
  let output = html;
  for (const [key, val] of Object.entries(merged)) {
    const reg = new RegExp("{{\\s*" + key + "\\s*}}", "g");
    output = output.replace(reg, val);
  }
  return output;
}

export default async function handler(req: VercelRequest, res: VercelResponse) {
  const smtpUser = process.env.SMTP_USER || process.env.EMAIL_USER || process.env.GMAIL_USER || "";
  const smtpPass = process.env.SMTP_PASS || process.env.EMAIL_PASS || process.env.GMAIL_APP_PASS || process.env.GMAIL_PASS || "";
  const targetEmail = (req.query.to as string) || "janegracy.int2027g3@gmail.com";

  if (!smtpUser || !smtpPass) {
    return res.status(500).json({
      success: false,
      error: "SMTP credentials missing in Vercel environment variables (SMTP_USER / SMTP_PASS).",
    });
  }

  const transporter = nodemailer.createTransport({
    service: "gmail",
    auth: {
      user: smtpUser,
      pass: smtpPass,
    },
    pool: false,
    secure: true,
  });

  const requestedSingle = req.query.template as string;
  const toSend = requestedSingle
    ? TEMPLATE_SPECS.filter((t) => t.id === requestedSingle || t.file === requestedSingle)
    : TEMPLATE_SPECS;

  if (toSend.length === 0) {
    return res.status(400).json({
      success: false,
      error: `Unknown template '${requestedSingle}'. Available: welcome, advertising, business-value, reengagement, lead-generation, products-features`,
    });
  }

  const results: any[] = [];

  for (const item of toSend) {
    try {
      const rawHtml = getTemplateSource(item.file);
      if (!rawHtml) {
        throw new Error(`Template ${item.file} not found in disk or bundle`);
      }

      const renderedHtml = renderPlaceholders(rawHtml, {
        name: (req.query.name as string) || DEFAULT_VARIABLES.name,
        email: (req.query.email as string) || targetEmail,
      });

      const info = await transporter.sendMail({
        from: `"Physiomatics" <${smtpUser}>`,
        to: targetEmail,
        subject: item.subject,
        html: renderedHtml,
        replyTo: smtpUser,
      });

      console.log(`[SendTemplates] Sent ${item.id} -> ${targetEmail} (ID: ${info.messageId})`);
      results.push({
        template: item.id,
        file: item.file,
        status: "DELIVERED",
        messageId: info.messageId,
      });
    } catch (err: any) {
      console.error(`[SendTemplates] Failed to send ${item.id}:`, err);
      results.push({
        template: item.id,
        file: item.file,
        status: "FAILED",
        error: err?.message || String(err),
      });
    }
  }

  return res.status(200).json({
    success: true,
    recipient: targetEmail,
    total_requested: toSend.length,
    sent_count: results.filter((r) => r.status === "DELIVERED").length,
    results,
  });
}
